+  existingRules: AgentDispatchRule[] | undefined,
+  options: {
+    addDispatchRule?: string[] | string;
+    removeDispatchRule?: string;
+    clearDispatchRules?: boolean;
+  },
+): AgentDispatchRule[] {
+  let nextRules = [...(existingRules ?? [])];
