 65	function resolveMetaRefToUlid(
 66	  ref: string,
 67	  metaCtx: MetaContext,
 68	): {
 69	  ulid: string;
 70	  type: "agent" | "workflow" | "convention" | "observation" | "skill";
 71	} | null {
 72	  const result = resolveMetaRef(metaCtx, ref);
 73	  if (!result) return null;
