 84	function parseDispatchRuleOption(rawRule: string): AgentDispatchRule {
 85	  let parsedRule: unknown;
 86	  try {
 87	    parsedRule = JSON.parse(rawRule);
 88	  } catch (err) {
 89	    const message = err instanceof Error ? err.message : String(err);
 90	    throw new Error(`Invalid JSON in --add-dispatch-rule: ${message}`);
 91	  }
 92	
 93	  const parsed = AgentDispatchRuleSchema.safeParse(parsedRule);
 94	  if (!parsed.success) {
 95	    const issues = parsed.error.issues
 96	      .map((issue) => `${issue.path.join(".") || "rule"}: ${issue.message}`)
 97	      .join("; ");
 98	    throw new Error(`Invalid dispatch rule in --add-dispatch-rule: ${issues}`);
 99	  }
100	
101	  return parsed.data;
102	}
